    <style>
        [x-cloak] {
            display: none !important;
        }

        * {
            font-family: 'Cairo', sans-serif;
        }

        html {
            scroll-behavior: smooth;
        }

        .hero-gradient {
            background: linear-gradient({{ session('locale', 'en') === 'ar' ? '90deg' : '270deg' }},
                    rgba(58, 82, 42, 0) 0%,
                    rgba(58, 82, 42, 0.1) 30%,
                    rgba(58, 82, 42, 0.8) 70%,
                    rgba(58, 82, 42, 1) 100%);
        }

        .abstract-dots {
            background-image: radial-gradient(rgba(58, 82, 42, 0.1) 2px, transparent 2px);
            background-size: 20px 20px;
        }

        /* CSS Variables */
        :root {
            --color-primary-green: #3A522A;
            --color-primary-green-dark: #29391D;
            --color-beige-light: #E9F4D3;
            --color-accent-lime-light: #D9E4C1;
            --color-text-primary: #3A522A;
            --color-text-secondary: #5a6f4a;
            --color-white: #ffffff;
            --spacing-sm: 0.5rem;
            --spacing-md: 1rem;
            --spacing-lg: 1.5rem;
            --spacing-xl: 2rem;
            --spacing-2xl: 3rem;
            --spacing-3xl: 4rem;
            --radius-md: 0.75rem;
            --radius-lg: 1rem;
            --radius-2xl: 1.5rem;
            --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
            --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
            --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.1);
            --transition-base: 0.3s ease;
            --transition-slow: 0.5s ease;
            --font-weight-extra-bold: 800;
        }

        /* Why Us Section Styles */
        .why-us-section {
            background-color: var(--color-white);
            padding: 5rem 0;
        }

        .why-us-section .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 1rem;
        }

        .section-title {
            text-align: center;
            color: var(--color-text-primary);
            margin-bottom: var(--spacing-xl);
        }

        /* New Layout: Left Cards Grid + Right Title/Image */
        .why-us-layout {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--spacing-3xl);
            align-items: center;
            margin-top: var(--spacing-2xl);
        }

        /* Left Side: 2x2 Grid of Cards - Staggered Layout */
        .why-us-cards-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: var(--spacing-lg);
            padding-top: 50px;
        }

        /* Staggered effect: Right column (odd cards) shifted upward */
        .why-us-cards-grid .why-card:nth-child(odd) {
            transform: translateY(-50px);
        }

        .why-card {
            background-color: var(--color-accent-lime-light);
            padding: var(--spacing-xl);
            border-radius: var(--radius-lg);
            transition: all var(--transition-base);
            box-shadow: var(--shadow-sm);
            text-align: right;
        }

        .why-card:hover {
            transform: translateY(-5px);
            box-shadow: var(--shadow-md);
        }

        .why-icon {
            width: 56px;
            height: 56px;
            background-color: var(--color-primary-green);
            color: var(--color-white);
            border-radius: var(--radius-md);
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: var(--spacing-md);
            margin-right: auto;
        }

        .why-card h3 {
            color: var(--color-text-primary);
            font-size: 1.25rem;
            margin-bottom: var(--spacing-sm);
            font-weight: 700;
        }

        .why-card p {
            color: var(--color-text-secondary);
            line-height: 1.7;
            margin: 0;
            font-size: 0.95rem;
        }

        /* Right Side: Title, Subtitle and Image */
        .why-us-right {
            display: flex;
            flex-direction: column;
            gap: var(--spacing-xl);
        }

        .why-us-header {
            text-align: right;
        }

        .section-title-right {
            color: var(--color-text-primary);
            font-size: clamp(1.75rem, 4vw, 2.25rem);
            font-weight: var(--font-weight-extra-bold);
            margin-bottom: var(--spacing-sm);
            line-height: 1.3;
        }

        .section-subtitle-right {
            color: var(--color-text-secondary);
            font-size: 1.125rem;
            line-height: 1.7;
            margin: 0;
        }

        .why-us-image-wrapper {
            position: relative;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .decorative-shape {
            position: absolute;
            width: 100%;
            height: 100%;
            background: linear-gradient(135deg, var(--color-primary-green) 0%, rgba(5, 51, 3, 0.8) 100%);
            border-radius: 50% 30% 50% 30%;
            transform: rotate(-10deg);
            z-index: 0;
            filter: blur(20px);
            opacity: 0.3;
        }

        .food-image {
            position: relative;
            width: 100%;
            max-width: 450px;
            height: auto;
            /* border-radius: var(--radius-2xl); */
            /* box-shadow: var(--shadow-lg); */
            transform: rotate(-3deg);
            transition: transform var(--transition-slow);
            z-index: 1;
        }

        .food-image:hover {
            transform: rotate(0deg) scale(1.05);
        }

        /* Responsive Design for Why Us Section */
        @media (max-width: 1024px) {
            .why-us-layout {
                grid-template-columns: 1fr;
                gap: var(--spacing-2xl);
            }

            .why-us-right {
                order: -1;
            }

            .why-us-header {
                text-align: center;
            }

            .section-title-right,
            .section-subtitle-right {
                text-align: center;
            }
        }

        @media (max-width: 640px) {
            .why-us-cards-grid {
                grid-template-columns: 1fr;
                padding-top: 0;
            }

            /* Reset staggered effect on mobile */
            .why-us-cards-grid .why-card:nth-child(odd) {
                transform: none;
            }

            .why-card {
                text-align: center;
            }

            .why-icon {
                margin: 0 auto var(--spacing-md) auto;
            }
        }

        /* Hero Abstract Shape */
        .side-abstract {
            position: absolute;
            top: 0;
            height: 100%;
            width: auto;
            max-width: 50vw;
            z-index: 0;
            pointer-events: none;
        }

        .side-abstract-right {
            right: 0;
            transform: scaleX(-1);
        }

        .side-abstract-left {
            left: 0;
        }
    </style>
</head>

